adjustDate: function(sign, days) {

    var day = this.getDate() || new Date();
    var difference = parseInt(days)*24*60*60*1000;

    var newDay;

    if (sign === 'add') {
        newDay = new Date(day.valueOf() + difference);
    } else if (sign === 'subtract') {
        newDay = new Date(day.valueOf() - difference);
    }

    // Skip disabled days
    if (this._o.disableDayFn && typeof this._o.disableDayFn === 'function') {
        var limit = 1000; // safety
        while (limit--) {
            if (!this._o.disableDayFn(newDay)) {
                break;
            }
            if (sign === 'add') {
                newDay = new Date(newDay.valueOf() + 24*60*60*1000);
            } else {
                newDay = new Date(newDay.valueOf() - 24*60*60*1000);
            }
            // Respect min/max
            var min = this._o.minDate,
                max = this._o.maxDate;
            if (min && newDay < min) {
                newDay = min;
                break;
            }
            if (max && newDay > max) {
                newDay = max;
                break;
            }
        }
    }

    this.setDate(newDay);
},
